"""Process-wide registry of created metric instruments.

Instrument packages (voice, turn) declare their instruments as
:class:`~rasa.tracing.shared.instrument_spec.InstrumentSpec` tuples and
register them here against the configured SDK meter provider. Recording
functions look instruments up by metric name and stay safe no-ops until
registration runs (from ``rasa.tracing.metrics_config.configure_metrics``).
"""

from __future__ import annotations

from typing import Dict, Optional, Tuple, Union

import structlog
from opentelemetry import metrics as otel_metrics
from opentelemetry.metrics import Counter, Histogram
from opentelemetry.sdk.metrics import MeterProvider as SdkMeterProvider

from rasa.tracing.shared.instrument_spec import InstrumentSpec

structlogger = structlog.get_logger()

_instruments: Dict[str, Union[Histogram, Counter]] = {}


def register_instruments(meter_name: str, specs: Tuple[InstrumentSpec, ...]) -> None:
    """Create the given instruments on a meter of the configured SDK provider.

    If no SDK meter provider is configured, registration is skipped and
    :func:`instruments_registered` remains false.

    Args:
        meter_name: Name of the meter the instruments belong to.
        specs: Declarative specs of the instruments to create.
    """
    meter_provider = otel_metrics.get_meter_provider()
    if not isinstance(meter_provider, SdkMeterProvider):
        structlogger.debug(
            "metric_instruments.registration_skipped",
            meter_name=meter_name,
            event_info=(
                "No SDK meter provider is configured; these metrics stay disabled."
            ),
        )
        return

    meter = meter_provider.get_meter(meter_name)
    _instruments.update({spec.name: spec.create(meter) for spec in specs})


def get_registered_instrument(name: str) -> Optional[Union[Histogram, Counter]]:
    """Return a registered instrument by metric name, if any."""
    return _instruments.get(name)


def reset_registered_instruments() -> None:
    """Clear all registered instruments (used by tests)."""
    _instruments.clear()


def instruments_registered() -> bool:
    """Return whether any metric instruments are registered."""
    return bool(_instruments)
